import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'
import { ScrollableTabs } from '@/components/shared/ScrollableTabs'

interface TabDef {
  label: string
  href: string
  count?: number
}

interface ClientTabNavProps {
  clientId: string
  counts?: {
    photos?: number
    notes?: number
    files?: number
    comms?: number
  }
}

export function ClientTabNav({ clientId, counts }: ClientTabNavProps) {
  const pathname = usePathname()

  const tabs: TabDef[] = [
    { label: 'Overview', href: `/clients/${clientId}/overview` },
    { label: 'Appointments', href: `/clients/${clientId}/appointments` },
    { label: 'Photos', href: `/clients/${clientId}/photos`, ...(counts?.photos !== undefined ? { count: counts.photos } : {}) },
    { label: 'Notes', href: `/clients/${clientId}/notes`, ...(counts?.notes !== undefined ? { count: counts.notes } : {}) },
    { label: 'Files', href: `/clients/${clientId}/files`, ...(counts?.files !== undefined ? { count: counts.files } : {}) },
    { label: 'Comms', href: `/clients/${clientId}/comms`, ...(counts?.comms !== undefined ? { count: counts.comms } : {}) },
    { label: 'Consent', href: `/clients/${clientId}/consent` },
    { label: 'Financial', href: `/clients/${clientId}/financial` },
  ]

  return (
    <ScrollableTabs>
    <nav
      className="flex items-center gap-0"
      aria-label="Client profile tabs"
    >
      {tabs.map((tab) => {
        const isActive = pathname === tab.href || (tab.href !== `/clients/${clientId}/overview` && pathname.startsWith(tab.href))
        return (
          <Link
            key={tab.href}
            href={tab.href}
            data-active={isActive}
            className={cn(
              'relative px-3 py-2.5 text-sm font-medium text-muted-foreground',
              'hover:text-foreground transition-colors duration-150 ease-out',
              'whitespace-nowrap flex items-center gap-1',
              "after:absolute after:bottom-0 after:left-0 after:right-0 after:h-0.5 after:rounded-full after:transition-opacity after:duration-150",
              isActive
                ? 'text-foreground after:bg-primary after:opacity-100'
                : 'after:opacity-0'
            )}
          >
            {tab.label}
            {tab.count !== undefined && tab.count > 0 && (
              <span className="bg-muted text-muted-foreground text-[10px] rounded-full min-w-[1.125rem] h-[1.125rem] flex items-center justify-center px-0.5 tabular-nums">
                {tab.count > 99 ? '99+' : tab.count}
              </span>
            )}
          </Link>
        )
      })}
    </nav>
    </ScrollableTabs>
  )
}

