async function getSignedUrl(storagePath: string): Promise<string> {
  'use server'
  const { createClient: createServerClient } = await import('@/lib/supabase/server')
  const supabase = await createServerClient()
  const { data } = await supabase.storage
    .from('booking-photos')
    .createSignedUrl(storagePath, 3600)
  return data?.signedUrl ?? ''
}

export default async function Page({ params }: Props) {
  const { id } = await params

  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  const [photosResult, bookingsResult] = await Promise.all([
    supabase
      .from('booking_photos')
      .select('id, storage_path, kind, caption, booking_id')
      .eq('client_id', id)
      .eq('studio_id', auth.studioId)
      .order('created_at', { ascending: false }),
    supabase
      .from('bookings')
      .select('id, scheduled_at, services(name), artists(display_name)')
      .eq('client_id', id)
      .eq('studio_id', auth.studioId)
      .order('scheduled_at', { ascending: false }),
  ])

  const rawPhotos = (photosResult.data ?? []).map((p) => ({
    id: p.id,
    storagePath: p.storage_path,
    kind: p.kind,
    caption: p.caption,
    bookingId: p.booking_id,
  }))

  type BookingWithJoins = {
    id: string
    scheduled_at: string
    services?: { name: string } | null
    artists?: { display_name: string } | null
  }

  const bookings = (bookingsResult.data ?? []).map((b) => {
    const bj = b as BookingWithJoins
    return {
      id: bj.id,
      scheduledAt: bj.scheduled_at,
      serviceName: bj.services?.name ?? null,
      artistName: bj.artists?.display_name ?? null,
    }
  })

  return (
    <ClientPhotoGallery
      photos={rawPhotos}
      bookings={bookings}
      getSignedUrl={getSignedUrl}
    />
  )
}

